function debounce(func, wait = 0, immediate = false) {
  let timeoutId = null;

  return function debounced(...args) {
    const callNow = immediate && !timeoutId;

    // Clear any pending execution
    if (timeoutId) {
      clearTimeout(timeoutId);
    }

    // Set a new timeout
    timeoutId = setTimeout(() => {
      timeoutId = null;
      if (!immediate) {
        func.apply(this, args);
      }
